286	    /**
287	     * The owner's membership level, a number from 1 to 4, derived from {@link #getMembershipPoints()}:
288	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more
289	     * points.
290	     */
291	    @Transient
292	    public Integer getMembershipLevel() {
293	        int points = getMembershipPoints();
294	        if (points <= 1) {
295	            return 1;
296	        }
297	        if (points <= 3) {
298	            return 2;
299	        }
300	        if (points <= 5) {
301	            return 3;
302	        }
303	        return 4;
304	    }
305	
306	    /** City -> canonical region for the {@code region} derivation. */
307	    private static final Map<String, String> CITY_REGION = Map.of(
308	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
309	
310	    /** Region -> inclusive 4-digit postcode range {low, high} for the {@code region} derivation. */
311	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
312	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
313	
314	    /**
315	     * The region code that forms the {@code REGION} segment of the {@link #customerCode}, derived
316	     * by looking up the region by {@link #postcode} range first (NSW 2000-2099, VIC 3000-3099,
317	     * QLD 4000-4099), and only falling back to the fixed city-to-region table (Sydney->NSW,
318	     * Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no known range. Returns
319	     * {@code UNKNOWN} when neither source resolves a region.
320	     */
321	    @Transient
322	    public String getRegion() {
323	        String region = regionForPostcode(this.postcode);
324	        if (region != null) {
325	            return region;
326	        }
327	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
328	    }
329	
330	    /**
331	     * The owner's locality: the {@code REGION} segment of its {@link #customerCode} (everything
332	     * before the first {@code '-'}). Because the customer code is {@code <REGION>-<HASH8>} with
333	     * {@code REGION} derived from the postcode, the locality now simply reads that region back off
334	     * the identity. Returns {@code UNKNOWN} until a customer code is assigned.
335	     */
336	    @Transient
337	    public String getLocality() {
338	        if (this.customerCode == null) {
339	            return "UNKNOWN";
340	        }
341	        int dash = this.customerCode.indexOf('-');
342	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
343	    }
344	
345	    /** Region whose postcode range contains the given postcode, or {@code null} when none does. */
346	    private static String regionForPostcode(String postcode) {
347	        if (postcode == null) {
348	            return null;
349	        }
350	        int value;
351	        try {
352	            value = Integer.parseInt(postcode.trim());
353	        }
354	        catch (NumberFormatException ex) {
355	            return null;
356	        }
357	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
358	            int[] range = entry.getValue();
359	            if (value >= range[0] && value <= range[1]) {
360	                return entry.getKey();
361	            }
362	        }
363	        return null;
364	    }
365	
366	    /**
367	     * The owner's identity key, the single derived value all duplicate detection is based on. It is
368	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone
369	     * is the stored E.164 value, the email is the stored lower-cased value (empty when absent) and
370	     * the household segment is the deterministic {@code householdId} derived from the last name and
371	     * postcode (empty only when no household id has been assigned). Two owners are duplicates only
372	     * when their whole identity keys are equal.
373	     */
374	    @Transient
375	    public String getIdentityKey() {
376	        String telephonePart = this.telephone == null ? "" : this.telephone;
377	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
378	        String householdPart = this.householdId == null ? "" : this.householdId;
379	        return telephonePart + "|" + emailPart + "|" + householdPart;
380	    }
