430	    protected Set<Pet> getPetsInternal() {
431	        if (this.pets == null) {
432	            this.pets = new HashSet<>();
433	        }
434	        return this.pets;
435	    }
436	
437	    protected void setPetsInternal(Set<Pet> pets) {
438	        this.pets = pets;
439	    }
440	
441	    public List<Pet> getPets() {
442	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
443	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
444	        return Collections.unmodifiableList(sortedPets);
445	    }
446	
447	    public void setPets(List<Pet> pets) {
448	        this.pets = new HashSet<>(pets);
449	    }
450	
451	    public void addPet(Pet pet) {
452	        getPetsInternal().add(pet);
453	        pet.setOwner(this);
454	    }
455	
456	    /**
457	     * Return the Pet with the given name, or null if none found for this Owner.
458	     *
459	     * @param name to test
460	     * @return true if pet name is already in use
461	     */
462	    public Pet getPet(String name) {
463	        return getPet(name, false);
464	    }
465	
466	    /**
467	     * Return the Pet with the given name, or null if none found for this Owner.
468	     *
469	     * @param name to test
470	     * @return true if pet name is already in use
471	     */
472	    public Pet getPet(String name, boolean ignoreNew) {
473	        name = name.toLowerCase();
474	        for (Pet pet : getPetsInternal()) {
475	            if (!ignoreNew || !pet.isNew()) {
476	                String compName = pet.getName();
477	                compName = compName.toLowerCase();
478	                if (compName.equals(name)) {
479	                    return pet;
480	                }
481	            }
482	        }
483	        return null;
484	    }
485	
486	    public Pet getPet(Integer petId) {
487	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
488	    }
489	
490	    @Override
491	    public String toString() {
492	        return new ToStringCreator(this)
493	
494	            .append("id", this.getId())
495	            .append("new", this.isNew())
496	            .append("lastName", this.getLastName())
497	            .append("firstName", this.getFirstName())
498	            .append("address", this.address)
499	            .append("city", this.city)
500	            .append("telephone", this.telephone)
501	            .append("email", this.email)
502	            .toString();
503	    }
504	}
